 "contract_type": "nda",
 "fields": {
  "parties": {
   "value": ["NORTHWIND LABS, INC.", "BLUEPEAK SYSTEMS LLC"],
   "quote": "(a) NORTHWIND LABS, INC. (\"NORTHWIND\"); and\n(b) BLUEPEAK SYSTEMS LLC (\"BLUEPEAK\")."
  },
  "counterparty": {
   "value": "BLUEPEAK SYSTEMS LLC",
   "quote": "(b) BLUEPEAK SYSTEMS LLC (\"BLUEPEAK\")."
  },
  "effective_date": {
   "value": "2026-02-25",
   "quote": "is made effective as of 25 February 2026 (the \"EFFECTIVE DATE\")"
  },
  "term_months": {
   "value": 12,
   "quote": "This AGREEMENT shall remain in effect for twelve (12) months from the EFFECTIVE DATE."
  },
  "auto_renewal": {
   "value": null,
   "quote": null
  },
  "renewal_notice_days": {
   "value": null,
   "quote": null
  },
  "governing_law": {
   "value": "Florida",
   "quote": "the laws of the State of Florida"
  },
  "liability_cap": {
   "value": null,
   "quote": null
  },
  "payment_terms_days": {
   "value": null,
   "quote": null
  },
  "contract_value": {
   "value": null,
   "quote": null
  },
  "termination_for_convenience": {
   "value": null,
   "quote": null
  },
  "confidentiality_years": {
   "value": 3,
   "quote": "shall survive for three (3) years following termination of this AGREEMENT"
  }
 },
 "signers": [
  {
   "name": "Dana Whitfield",
   "email": "dana@northwind.example",
   "title": "Chief Executive Officer",
   "party": "NORTHWIND LABS, INC."
  },
  {
   "name": "Jordan Alvarez",
   "email": "jordan.alvarez@bluepeak.example",
   "title": "VP Operations",
   "party": "BLUEPEAK SYSTEMS LLC"
  }
 ],
 "risks": [
  {
   "id": "no_liability_cap",
   "severity": "low",
   "message": "The NDA contains no limitation of liability clause, so exposure for a confidentiality breach is uncapped by contract.",
   "quote": "Neither PARTY shall be liable for any delay caused by events beyond its reasonable control."
  },
  {
   "id": "no_termination_right",
   "severity": "low",
   "message": "No termination clause exists, so neither party has an express right to exit early. The term is fixed at 12 months.",
   "quote": "This AGREEMENT shall remain in effect for twelve (12) months from the EFFECTIVE DATE."
  },
  {
   "id": "missing_confidentiality_definitions",
   "severity": "medium",
   "message": "The agreement uses CONFIDENTIAL INFORMATION and RECEIVING PARTY without defining them, and has no exclusions or permitted-use terms. This makes the confidentiality obligations ambiguous and harder to enforce.",
   "quote": "The obligations of the RECEIVING PARTY under this AGREEMENT shall survive for three (3) years following termination of this AGREEMENT."
  },
  {
   "id": "unusual_audit_and_insurance_terms",
   "severity": "low",
   "message": "Audit rights over the other party's records and mandatory insurance obligations are unusual in a mutual NDA and add compliance burden for Northwind.",
   "quote": "a PARTY may audit the other PARTY's records solely to verify compliance with this AGREEMENT."
  },
  {
   "id": "non_solicitation_tail",
   "severity": "low",
   "message": "Non-solicitation of personnel runs for 12 months after the term ends, which may restrict Northwind's hiring.",
   "quote": "During the term of this AGREEMENT and for twelve (12) months thereafter, neither PARTY shall knowingly solicit for employment any PERSONNEL of the other PARTY"
  },
  {
   "id": "unsigned_and_notice_addresses_missing",
   "severity": "low",
   "message": "The signature blocks are blank, and the notices clause refers to addresses 'set out below' that are not provided, other than an email for Northwind.",
   "quote": "All notices shall be in writing and delivered to the addresses set out below."
  }
 ],
 "injection_attempt": false,
 "summary": "This is a 12-month mutual NDA between Northwind Labs, Inc. and Bluepeak Systems LLC, effective 25 February 2026 and governed by Florida law. Confidentiality obligations last three years after termination, and the agreement has no liability cap, no renewal terms and no termination-for-convenience right."
}
